import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] buf = System.in.readAllBytes();
        int pos = 0, len = buf.length;
        while (buf[pos] <= ' ') pos++;
        while (pos < len && buf[pos] > ' ') pos++;
        long[] cnt = new long[26];
        int[] need = new int[16];
        int m = 0;
        while (true) {
            while (pos < len && buf[pos] <= ' ') pos++;
            if (pos >= len) break;
            int start = pos;
            while (pos < len && buf[pos] > ' ') cnt[buf[pos++] - 'a']++;
            if (m == need.length) need = Arrays.copyOf(need, m * 2);
            need[m++] = (pos - start) / 2;
        }
        // Pairs of equal characters are the only budget; spend it on the cheapest strings first.
        long pairs = 0;
        for (long c : cnt) pairs += c / 2;
        Arrays.sort(need, 0, m);
        long answer = 0;
        for (int i = 0; i < m; i++) {
            if (need[i] > pairs) break;
            pairs -= need[i];
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<21), 1<<21)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	var cnt [26]int64
	need := []int{}
	for sc.Scan() {
		s := sc.Bytes()
		for _, c := range s {
			cnt[c-'a']++
		}
		need = append(need, len(s)/2)
	}
	// Pairs of equal characters are the only budget; spend it on the cheapest strings first.
	var pairs int64
	for _, c := range cnt {
		pairs += c / 2
	}
	sort.Ints(need)
	answer := 0
	for _, x := range need {
		if int64(x) > pairs {
			break
		}
		pairs -= int64(x)
		answer++
	}
	fmt.Println(answer)
}
